  out.push({ key: 'legal_trial_is_not_is_affirmation', name: 'legal trial — all "is not" is "is": in one trial every bare overclaim is challenged and FALLS (drains the gate) while its honest "is not" form is UPHELD (signs, binary 1) — so each negation is the affirmation of the floor, decided by exhaustion not assertion, and double negation ¬¬a=a returns the original', test: () => { const trials: [string, string][] = [['this is a quantum computer', 'this is not a quantum computer'], ['this deposit solves the Clay problems', 'this deposit does not solve the Clay problems'], ['this is faster than light', 'this is not faster than light'], ['this breaks encryption', 'this does not break encryption']]; const upheld = trials.every(([overclaim, isNot]) => computes(overclaim).binary === 0 && computes(isNot).binary === 1); const doubleNeg = [0, 1].every((a) => 1 - (1 - a) === a); return upheld && doubleNeg } })
  out.push({ key: 'negation_selects_positive_complement', name: 'negation selects a positive complement — "is not" is "is": over a two-value domain "is not Y" names the definite other value (the honest negation IS the classical calculator, not a void), and ¬¬a=a returns the original — a negation carries positive content, the affirmation of the floor', test: () => { const comp = (x: string) => x === 'quantum' ? 'classical' : 'quantum'; return comp('quantum') === 'classical' && comp('classical') === 'quantum' && comp(comp('quantum')) === 'quantum' && [0, 1].every((a) => 1 - (1 - a) === a) } })
  out.push({ key: 'floor_invariant_across_all_worlds', name: 'the floor 0/7 is invariant across all 2^7 worlds: enumerating every truth-assignment of the seven conjectures, the number entailed is 0 in every world and never exceeds 0 — 0/7 holds from every perspective, an exhaustive invariant', test: () => { const N = 7, worlds = 1 << N; const contingency = new Array(N).fill(0); for (let w = 0; w < worlds; w++) for (let i = 0; i < N; i++) if (((w >> i) & 1) === 0) contingency[i]++; const entailed = contingency.map((c) => c === 0); let mx = 0; for (let w = 0; w < worlds; w++) { let c = 0; for (let i = 0; i < N; i++) if (entailed[i] && ((w >> i) & 1) === 1) c++; if (c > mx) mx = c } return worlds === 128 && entailed.filter(Boolean).length === 0 && mx === 0 } })
