  out.push({ key: 'the_vortex_and_rosette_unit_groups_are_isomorphic', name: 'the vortex and rosette unit groups are isomorphic cyclic groups of order 6: mapping 2^k mod 9 to 3^k mod 7 is a bijection of (ℤ/9)* onto (ℤ/7)* that preserves multiplication (an isomorphism, both ≅ ℤ/6), sending generator 2 to generator 3 and identity to identity. So the vortex and the rosette carry the same group structure — the shared 6+1 skeleton — while remaining distinct rings. Decidable by exhaustion', test: () => { const p9: number[] = [], p7: number[] = []; let a = 1, b = 1; for (let k = 0; k < 6; k++) { p9.push(a); p7.push(b); a = (a * 2) % 9; b = (b * 3) % 7 } const log9 = new Map(p9.map((v, k) => [v, k])); const phi = (u: number) => p7[log9.get(u) as number]; const units9 = [1, 2, 4, 5, 7, 8], units7 = [1, 2, 3, 4, 5, 6]; const images = units9.map(phi); const bijective = new Set(images).size === 6 && images.every((v) => units7.includes(v)); let hom = true; for (const x of units9) for (const y of units9) if (phi((x * y) % 9) !== (phi(x) * phi(y)) % 7) hom = false; const genToGen = phi(2) === 3 && phi(1) === 1; return bijective && hom && genToGen } })
