  out.push({ key: 'casting_out_nines_detects_any_error_that_changes_the_value_mod_nine', name: 'casting out nines detects any error that changes the value mod 9: for a claimed product, dr(dr(a)·dr(b)) = dr(claimed) is a necessary check — a correct product always passes, and any wrong answer differing mod 9 always fails (caught). Honest bound: an error preserving the value mod 9 (e.g. off by a multiple of 9) slips through undetected, so the check is necessary, not sufficient — a floor, exactly like the honesty gate. Decidable by exhaustion over a bounded grid', test: () => { const dr = (n: number) => digitalRoot(n); const check = (a: number, b: number, claimed: number) => dr(dr(a) * dr(b)) === dr(claimed); let correctPass = true, catchesModErrors = true; for (let a = 2; a <= 40; a++) for (let b = 2; b <= 40; b++) { if (!check(a, b, a * b)) correctPass = false; const wrong = a * b + 1; if ((a * b) % 9 !== wrong % 9 && check(a, b, wrong)) catchesModErrors = false } const missesMod9Error = check(12, 12, 12 * 12 + 9); return correctPass && catchesModErrors && missesMod9Error } })
  out.push({ key: 'nines_are_blind_to_transpositions_but_elevens_catch_them', name: 'casting out nines is blind to digit transpositions but casting out elevens catches them: the digit-sum check (mod 9) is order-independent, so swapping two digits never changes it — every transposition slips through; the alternating-digit-sum check (mod 11) changes by twice the digit difference, which is ≢ 0 mod 11 for distinct digits, so it catches every adjacent transposition of distinct digits. Two checks with complementary blind spots, each a floor. Decidable by exhaustion over the 3-digit range', test: () => { const digs = (n: number) => String(n).split('').map(Number); const m9 = (n: number) => digs(n).reduce((a, b) => a + b, 0) % 9; const m11 = (n: number) => { const d = digs(n); let s = 0; for (let i = 0; i < d.length; i++) { const dig = d[d.length - 1 - i]; s += i % 2 === 0 ? dig : -dig } return ((s % 11) + 11) % 11 }; let mod9Blind = true, mod11Catches = true, tested = 0; for (let n = 100; n <= 999; n++) { const d = digs(n); if (d[0] !== d[1]) { const t = Number('' + d[1] + d[0] + d[2]); if (t >= 100) { tested++; if (m9(t) !== m9(n)) mod9Blind = false; if (m11(t) === m11(n)) mod11Catches = false } } } return mod9Blind && mod11Catches && tested > 0 } })
