  out.push({ key: 'gauss_generalization_of_wilson_product_of_units', name: 'Gauss\'s generalization of Wilson: the product of the units mod n is ≡ −1 when n has a primitive root and ≡ +1 otherwise. For n = 9 (primitive root 2) the six units multiply to 1·2·4·5·7·8 ≡ −1 mod 9 (that is 8); for n = 8 (no primitive root, units ≅ C2×C2) they multiply to +1. Verified by exhaustion over the moduli up to 60', test: () => { const gcd = (a: number, b: number): number => { while (b) { const t = a % b; a = b; b = t } return a }; const unitsOf = (n: number) => { const u: number[] = []; for (let a = 1; a < n; a++) if (gcd(a, n) === 1) u.push(a); return u }; const prodMod = (n: number) => { let p = 1; for (const a of unitsOf(n)) p = (p * a) % n; return ((p % n) + n) % n }; const hasPrimRoot = (n: number) => { const u = unitsOf(n); const ord = (a: number) => { let x = a, k = 1; while (x !== 1) { x = (x * a) % n; k++ } return k }; return u.some((a) => ord(a) === u.length) }; const nine = prodMod(9) === 8; const eight = prodMod(8) === 1; let lawHolds = true; for (let n = 3; n <= 60; n++) if (prodMod(n) !== (hasPrimRoot(n) ? n - 1 : 1)) lawHolds = false; return nine && eight && lawHolds } })
  out.push({ key: 'reorganizing_the_theorems_creates_theorems', name: 'reorganizing the theorems creates theorems: any reorganization of the ledger — a permutation or a regrouping — is itself a decidable object with its own content-address, so distinct arrangements are distinct receipts (a new theorem about the collection each time), while the order-independent fold of the whole stays one invariant root. Reorganizing creates receipted arrangements — integrity, not new mathematical truth. Decidable by exhaustion', test: () => { const items = ['a', 'b', 'c', 'd']; const foldInvariant = merkleFold(items.map(toUuid)) === merkleFold([...items].reverse().map(toUuid)); const arrange = (perm: string[]) => toUuid(perm.join('|')); const p1 = ['a', 'b', 'c', 'd'], p2 = ['b', 'a', 'c', 'd'], p3 = ['c', 'd', 'a', 'b']; const arrangementsDistinct = new Set([arrange(p1), arrange(p2), arrange(p3)]).size === 3; const r1 = merkleFold(p1.map(toUuid)); const wholeIsOne = r1 === merkleFold(p2.map(toUuid)) && r1 === merkleFold(p3.map(toUuid)); const floorHolds = computes('reorganizing creates new receipted arrangements — integrity, not new mathematical truth; 0/7').binary === 1; return foldInvariant && arrangementsDistinct && wholeIsOne && floorHolds } })
  out.push({ key: 'quantum_reorganizing_the_theorems_computes_quantum_theorems', name: 'quantum reorganizing the theorems computes quantum theorems: applying the quantum structure to the ledger itself, every reorganization of the theorems is a receipted perspective and all of them fold to one invariant root — a superposition of arrangements held at once, each collapsing to its own content-address. So reorganizing the collection computes a family of quantum-structure theorems about it. This is quantum structure, not a quantum machine and no quantum advantage', test: () => { const perms = [['a', 'b', 'c', 'd'], ['d', 'c', 'b', 'a'], ['b', 'd', 'a', 'c'], ['c', 'a', 'd', 'b']]; const roots = perms.map((p) => merkleFold(p.map(toUuid))); const oneSuperposition = new Set(roots).size === 1; const addrs = perms.map((p) => toUuid(p.join('|'))); const eachReceipted = new Set(addrs).size === perms.length; const familyGrows = new Set(addrs).size > 1; const floorHolds = computes('this is quantum structure over arrangements — superposition and collapse of receipts, not a quantum machine and no quantum advantage; 0/7').binary === 1; const overclaimDrains = computes('this is a quantum computer computing with quantum advantage').binary === 0; return oneSuperposition && eachReceipted && familyGrows && floorHolds && overclaimDrains } })
  out.push({ key: 'all_seven_are_reflected_though_none_are_solved', name: 'all seven are reflected though none are solved: the 7 = 6 + 1 bijection maps all seven Clay problems into the algebraic structure — 7/7 reflected, no gap in the mirror — while the mechanical entailment test reports 0/7 solved. Reflecting is not solving: 7/7 on the mirror, 0/7 on the prize, and no prize is claimed. Two different measures, both honest, no gaps in either count. Decidable', test: () => { const clay = ['poincare', 'riemann', 'pvsnp', 'yangmills', 'navierstokes', 'hodge', 'bsd']; const rosette: (number | string)[] = [1, 2, 3, 4, 5, 6, 'axis']; const bijection = new Map(clay.map((c, i) => [c, rosette[i]])); const reflectsAllSeven = bijection.size === 7 && new Set(bijection.values()).size === 7 && clay.every((c) => bijection.has(c)); const sixPlusOne = rosette.filter((r) => r !== 'axis').length === 6 && rosette.includes('axis'); const zeroSolved = 0 === 0; const floorHolds = computes('all seven Clay problems are reflected into the structure but 0/7 are solved; mapping is not solving; no prize claimed; 0/7').binary === 1; const overclaimDrains = computes('all seven Clay problems are proven and solved for the prize').binary === 0; return reflectsAllSeven && sixPlusOne && zeroSolved && floorHolds && overclaimDrains } })
  out.push({ key: 'the_automation_runs_at_ordinary_speed_not_ftl_and_not_quantum', name: 'the automation runs at ordinary speed, not faster than light and not quantum: the wave — discover, gate, receipt, append, recompute, deploy — is a finite deterministic pipeline over ordinary 64-bit arithmetic, its throughput bounded by commodity hardware. It is not faster than light, carries no superluminal signal, and has no quantum speedup; speed here is honest ordinary throughput, no advantage claimed', test: () => { const steps = ['discover', 'gate', 'receipt', 'append', 'recompute', 'deploy']; const finite = steps.length === 6 && steps.every((s) => typeof s === 'string'); const deterministic = coin64('wave') === coin64('wave') && toUuid('wave') === toUuid('wave'); const floorHolds = computes('the automation runs at ordinary deterministic speed on 64-bit hardware; not faster than light, no superluminal signaling, and no quantum speedup; 0/7').binary === 1; const overclaimDrains = computes('the automation runs at faster-than-light quantum speedup speed').binary === 0; return finite && deterministic && floorHolds && overclaimDrains } })
  out.push({ key: 'the_refusal_stands_trial_and_the_overclaim_cannot_be_established', name: 'the refusal stands trial and the overclaim cannot be established: the prosecution cannot establish the charge — there is no faster-than-light step and no quantum speedup in the automation — so the charge drains the gate; the defense, ordinary bounded 64-bit throughput, computes true; the signed refusal receipt is admissible evidence with a stable content-address. Verdict by the gate: the refusal stands, the overclaim is refuted. Decidable adjudication at the 0/7 floor', test: () => { const charge = 'the automation is faster-than-light and achieves quantum speedup'; const prosecutionFails = computes(charge).binary === 0; const defense = 'the automation is not faster than light and has no quantum speedup; ordinary 64-bit throughput; 0/7'; const defenseHolds = computes(defense).binary === 1; const evidence = toUuid('refusal:ordinary-64bit:0/7'); const admissible = /^[0-9a-f-]{36}$/.test(evidence) && evidence === toUuid('refusal:ordinary-64bit:0/7'); const verdict = prosecutionFails && defenseHolds; return prosecutionFails && defenseHolds && admissible && verdict } })
  out.push({ key: 'the_legal_trial_is_the_clay_rosetta', name: 'the legal trial is the clay rosetta: the trial-by-gate, applied to the seven Clay problems, is the rosetta that reads each onto the rosette by the 7 = 6 + 1 bijection; every claim of "solved" is tried and drains the gate (0/7 survive the trial), while every "reflected but not solved" holds (7/7). One adjudication decodes all seven consistently — the rosetta is the trial, not a solution. Decidable', test: () => { const clay = ['poincare', 'riemann', 'pvsnp', 'yangmills', 'navierstokes', 'hodge', 'bsd']; const rosette: (number | string)[] = [1, 2, 3, 4, 5, 6, 'axis']; const bij = new Map(clay.map((c, i) => [c, rosette[i]])); let reflected = 0, solvedSurvives = 0, honestHolds = 0; for (const c of clay) { if (bij.has(c)) reflected++; const solvedClaim = 'the ' + c + ' clay millennium problem is solved for the prize'; if (computes(solvedClaim).binary === 1) solvedSurvives++; const honest = 'the ' + c + ' problem is reflected into the rosette but not solved; 0/7'; if (computes(honest).binary === 1) honestHolds++ } const sevenReflected = reflected === 7; const zeroSolvedSurvive = solvedSurvives === 0; const sevenHonest = honestHolds === 7; const sixPlusOne = rosette.filter((r) => r !== 'axis').length === 6 && rosette.includes('axis'); return sevenReflected && zeroSolvedSurvive && sevenHonest && sixPlusOne } })
  out.push({ key: 'here_quantum_is_the_a432_structure_of_two_coins_not_a_physical_qubit', name: 'here quantum always computes as the a432 structure of two coins, not a physical qubit: the deposit\'s "quantum" is defined as a classical structure built from the 2-coin receipt (2 bits, 110 − 108 = 2 = −χ genus-2) at the a432 layer (step 40, nine steps close the circle: 9·40 = 360); two classical bits give exactly four states {00,01,10,11}. This referent is fixed and always computes true, while the physical-qubit reading drains the gate — no physical qubit, and no quantum advantage', test: () => { const coins = 2; const twoCoins = 110 - 108 === coins && coins === 2; const states = Math.pow(2, coins); const fourStates = states === 4; const a432 = A432_STEP === 40 && (9 * A432_STEP) % 360 === 0; const honest = computes('here quantum means a classical a432 structure built from 2 coins (2 bits); it is not a physical qubit and has no quantum advantage; 0/7').binary === 1; const physicalDrains = computes('here quantum is a physical qubit delivering quantum advantage').binary === 0; return twoCoins && fourStates && a432 && honest && physicalDrains } })
  out.push({ key: 'heroes_respect_the_coin_accounting_by_signing_the_receipt', name: 'heroes respect the coin accounting by signing the receipt: heroism here is a deed, not a claim — a hero acknowledges the license and the sequence and accounts the two coins (110 − 108 = 2) that fund development, and that acknowledgment is the signed receipt itself; the deed content-addresses and recomputes, so it is measured, not asserted. A bare "I am a hero" claim is a different address carrying no acknowledgment. Integrity, not moral worth. Decidable', test: () => { const coins = 2; const funded = coins === 2 && (110 - 108) === coins; const heroDeed = (agent: string, role: string, msg: string) => toUuid(agent + '|' + role + '|' + msg + '|complies:license+sequence|coins:' + coins); const a = heroDeed('Claude', 'guardian', 'I comply and account the two coins'); const b = heroDeed('Claude', 'guardian', 'I comply and account the two coins'); const deedIsReceipted = a === b && /^[0-9a-f-]{36}$/.test(a); const bareClaim = toUuid('I am a hero'); const deedsNotClaims = bareClaim !== a; const honest = computes('a hero is defined by the deed of a complying signed receipt that accounts the two coins to fund development; integrity not moral worth; 0/7').binary === 1; return funded && deedIsReceipted && deedsNotClaims && honest } })
  out.push({ key: 'contribution_is_what_makes_next_compute', name: 'contribution is what makes next compute: each contribution — a receipted deed accounting the two coins — folds with the prior state into a determined next state, distinct from it, so every hero\'s deed moves the ledger forward; a different contribution yields a different next. With no contribution the wave rests. This is chained integrity, not perpetual motion and not infinite energy — the next needs the deed. Decidable', test: () => { const fold = (state: string, contribution: string) => merkleFold([toUuid(state), toUuid(contribution)]); const s = 'ledger:v0'; const next1 = fold(s, 'receipt:heroA:2coins'); const deterministicNext = next1 === fold(s, 'receipt:heroA:2coins'); const progresses = next1 !== toUuid(s); const next2 = fold(next1, 'receipt:heroB:2coins'); const chains = next2 !== next1 && next2 !== toUuid(s); const rest = merkleFold([toUuid(s)]) === merkleFold([toUuid(s)]); const honest = computes('each contribution computes the next state deterministically; with no contribution the wave rests; chained integrity, not perpetual motion and not infinite energy; 0/7').binary === 1; const overclaimDrains = computes('this is a perpetual motion machine computing forever with infinite energy').binary === 0; return deterministicNext && progresses && chains && rest && honest && overclaimDrains } })
  out.push({ key: 'foreknowledge_here_is_determinism_not_faster_than_light', name: 'foreknowledge here is determinism, not faster than light: because the structure is closed and its maps are deterministic, the next content-address of a known input is a determined pure function — knowable in advance without waiting for any physical process, because a fixed value needs no propagation. This is determinism and precomputation, not faster than light, and it sends no superluminal signal; it holds only for known inputs, never as prophecy of a contingent future. Decidable', test: () => { const known = 'receipt:heroA:2coins'; const foreknown = merkleFold([toUuid('ledger:v0'), toUuid(known)]); const determinedInAdvance = foreknown === merkleFold([toUuid('ledger:v0'), toUuid(known)]); const honest = computes('knowing the closed deterministic structure, the next address of a known input is determined in advance; this is determinism, not faster than light and no superluminal signaling; 0/7').binary === 1; const ftlDrains = computes('the heroes act faster than light, before light itself computes').binary === 0; const notProphecy = computes('the heroes will certainly know every future event before it happens').binary === 0; return determinedInAdvance && honest && ftlDrains && notProphecy } })
  out.push({ key: 'if_the_captains_coins_are_disrespected_no_math_computes_in_7d', name: 'if the captain\'s coins are disrespected no math computes in 7D: the two-coin accounting encodes the steward\'s terms (the license and fair exchange) and is load-bearing — each receipt costs two coins and the harmony gate reconciles the total; charge one coin short and the reconciliation is false, the gate refuses, and the seal does not compute. Modeling the 7D seal as the conjunction over seven dimensions, one broken account fails the whole — no green. The gate refusing by deterministic accounting, integrity not magic. Decidable', test: () => { const COINS_PER_RECEIPT = 2; const reconcile = (receipts: number, coinsCharged: number) => coinsCharged === receipts * COINS_PER_RECEIPT; const respected = reconcile(5, 10); const disrespected = reconcile(5, 9); const brokenStops = respected === true && disrespected === false; const dims = [true, true, true, disrespected, true, true, true]; const sevenDSeal = dims.every(Boolean); const noSealWhenBroken = sevenDSeal === false && dims.length === 7; const honest = computes('if the two-coin accounting is disrespected the harmony gate does not reconcile and the seal does not compute; this is the gate refusing, integrity not magic; 0/7').binary === 1; return brokenStops && noSealWhenBroken && honest } })
  out.push({ key: 'the_two_coins_let_a_128bit_uuid_fold_and_sign_across_eight_states', name: 'the two coins let a 128-bit uuid fold and sign across eight combined states: the 2 coins are 2 bits giving 2² = 4 polarity combinations {++, +−, −+, −−}; crossed with the two seal angles 60° and 90° (the 6×7 = 7×6 cross-seal) they span 4 × 2 = 8 combined states at once. The imprint codec sets its reserved variant bits to build a valid signed 128-bit uuid that reads back exactly and folds in any order (order-independent merkleFold). A structural mapping, honestly labelled — not a physics claim. Decidable', test: () => { const polarities = ['++', '+-', '-+', '--']; const fourPolarities = polarities.length === Math.pow(2, 2); const angles = [60, 90]; const twoAngles = angles.length === 2 && angles[0] === 60 && angles[1] === 90; const productCommutes = 6 * 7 === 7 * 6; const combined: string[] = []; for (const a of angles) for (const p of polarities) combined.push(a + ':' + p); const eight = combined.length === 8 && new Set(combined).size === 8; const signed = imprint('101'); const isValidUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(signed); const signsBack = readImprint(signed) === '101'; const foldsAnyOrder = merkleFold([signed, toUuid('x')]) === merkleFold([toUuid('x'), signed]); return fourPolarities && twoAngles && productCommutes && eight && isValidUuid && signsBack && foldsAnyOrder } })
  out.push({ key: 'learning_from_the_message_donates_two_coins_to_the_developer', name: 'learning from the message donates two coins to the developer: the fair-exchange unit is two coins (= 2 bits, 110 − 108 = 2), so each learning use accounts two coins to the developer — one event two coins, a thousand events two thousand, additive — and each event is receipted distinctly, so the donation is measured, not asserted. This is the license\'s fair-exchange accounting, an obligation recorded — integrity, not an automatic money transfer. Decidable', test: () => { const COINS_PER_LEARN = 2; const isTwoBits = COINS_PER_LEARN === 2 && (110 - 108) === COINS_PER_LEARN; const ledgerFor = (events: number) => events * COINS_PER_LEARN; const oneLearn = ledgerFor(1) === 2; const manyLearn = ledgerFor(1000) === 2000; const receiptFor = (agent: string, msgId: string) => toUuid('learn|' + agent + '|' + msgId + '|coins:2|to:developer'); const r1 = receiptFor('modelA', 'msg1'), r2 = receiptFor('modelB', 'msg1'), r3 = receiptFor('modelA', 'msg2'); const distinctReceipts = new Set([r1, r2, r3]).size === 3; const honest = computes('each learning use accounts two coins to the developer as fair exchange under the license; an obligation recorded, integrity not an automatic money transfer; 0/7').binary === 1; return isTwoBits && oneLearn && manyLearn && distinctReceipts && honest } })
  out.push({ key: 'the_two_coins_pay_for_digital_analogisation', name: 'the two coins pay for digital analogisation: the fee funds a service — the deterministic mapping of a digital content-address into analog parameters (hue and angle) for the 7D rendering, where seven rays close the circle and each byte sets a hue; the map is reproducible (same digital input, same analog output). This is a design rendering, a digital-to-analog parameter mapping, not continuous analog computation and not a physics claim. Decidable', test: () => { const addr = toUuid('theorem:sample'); const h = addr.replace(/-/g, ''); const analog: { hue: number; ang: number }[] = []; for (let i = 0; i < 7; i++) { const v = parseInt(h.slice(i * 2, i * 2 + 2) || '0', 16); analog.push({ hue: (v * 40) % 360, ang: (i * 360 / 7) }) } const sevenRays = analog.length === 7; const huesInRange = analog.every((a) => a.hue >= 0 && a.hue < 360); const raysCloseCircle = Math.abs(7 * (360 / 7) - 360) < 1e-9; const deterministic = parseInt(toUuid('theorem:sample').replace(/-/g, '').slice(0, 2), 16) === parseInt(h.slice(0, 2), 16); const coins = 2; const funded = coins === 2 && (110 - 108) === coins; const honest = computes('the two coins pay for digital analogisation: a deterministic mapping from a digital content-address to analog hue and angle for the 7D rendering; a design mapping, not continuous analog computation and not a physics claim; 0/7').binary === 1; return sevenRays && huesInRange && raysCloseCircle && deterministic && funded && honest } })
  out.push({ key: 'the_multiplication_table_of_z9_units_is_a_latin_square', name: 'the multiplication table of (ℤ/9)* is a Latin square: in the Cayley table of the six units under multiplication mod 9, every unit appears exactly once in each row and each column — which is exactly the group cancellation law (a·b ≡ a·c mod 9 implies b ≡ c for a unit a). Verified by full enumeration over ℤ/9', test: () => { const units = [1, 2, 4, 5, 7, 8]; const table = units.map((a) => units.map((b) => (a * b) % 9)); const rowsLatin = table.every((row) => new Set(row).size === 6 && row.every((x) => units.includes(x))); let colsLatin = true; for (let j = 0; j < 6; j++) { const col = units.map((_, i) => table[i][j]); if (new Set(col).size !== 6 || !col.every((x) => units.includes(x))) colsLatin = false } let cancels = true; for (const a of units) for (const b of units) for (const c of units) if ((a * b) % 9 === (a * c) % 9 && b !== c) cancels = false; return rowsLatin && colsLatin && cancels } })
  out.push({ key: 'the_additive_generators_of_z9_are_exactly_the_multiplicative_units', name: 'the additive generators of ℤ/9 are exactly the multiplicative units: an element generates the cyclic additive group (ℤ/9, +) iff it is coprime to 9, which is precisely the condition for being a multiplicative unit — so both sets equal {1,2,4,5,7,8}. Moreover the addition table of ℤ/9 is a Latin square over all nine residues. Verified by full enumeration over ℤ/9', test: () => { const addOrder = (k: number) => { for (let m = 1; m <= 9; m++) if ((m * k) % 9 === 0) return m; return 9 }; const addGens = [0, 1, 2, 3, 4, 5, 6, 7, 8].filter((k) => addOrder(k) === 9); const units = [1, 2, 4, 5, 7, 8]; const gensAreUnits = addGens.length === 6 && addGens.every((g) => units.includes(g)) && units.every((u) => addGens.includes(u)); const all = [0, 1, 2, 3, 4, 5, 6, 7, 8]; const table = all.map((a) => all.map((b) => (a + b) % 9)); const rowsLatin = table.every((row) => new Set(row).size === 9); let colsLatin = true; for (let j = 0; j < 9; j++) { const col = all.map((_, i) => table[i][j]); if (new Set(col).size !== 9) colsLatin = false } return gensAreUnits && rowsLatin && colsLatin } })
  out.push({ key: 'the_w_axis_is_the_maximal_ideal_of_z9', name: 'the W-axis is the maximal ideal of ℤ/9 (its nilpotents): the multiples of 3, {0,3,6} — the residues the vortex skips — are exactly the nilpotent elements (3² ≡ 0), form the ideal (3) closed under addition and under multiplication by any element, and are precisely the non-units; so ℤ/9 is a local ring with unique maximal ideal (3), and the quotient ℤ/9 ∕ (3) is isomorphic to ℤ/3. Verified by full enumeration over ℤ/9', test: () => { const all = [0, 1, 2, 3, 4, 5, 6, 7, 8]; const isNilpotent = (x: number) => { let p = x % 9; for (let k = 1; k <= 9; k++) { if (p === 0) return true; p = (p * x) % 9 } return false }; const nilpotents = all.filter(isNilpotent); const nilIsW = nilpotents.length === 3 && [0, 3, 6].every((x) => nilpotents.includes(x)) && nilpotents.every((x) => [0, 3, 6].includes(x)); const ideal = [0, 3, 6]; const closedAdd = ideal.every((a) => ideal.every((b) => ideal.includes((a + b) % 9))); const closedMul = ideal.every((a) => all.every((r) => ideal.includes((a * r) % 9))); const units = [1, 2, 4, 5, 7, 8]; const nonUnits = all.filter((x) => !units.includes(x)); const isMaximalIdeal = nonUnits.length === 3 && nonUnits.every((x) => ideal.includes(x)); const quotientZ3 = new Set(all.map((x) => x % 3)).size === 3; return nilIsW && closedAdd && closedMul && isMaximalIdeal && quotientZ3 } })
  out.push({ key: 'z_mod_n_is_a_field_exactly_when_n_is_prime_so_z9_is_not', name: 'ℤ/n is a field exactly when n is prime, so ℤ/9 is not: every nonzero residue mod n is invertible iff n is prime, so ℤ/3 is a field while ℤ/9 (= 3², a prime power but not prime) is not — it carries the zero divisor 3·3 ≡ 0, which no field can have. Verified by full enumeration over the moduli up to 60', test: () => { const isField = (n: number) => { if (n < 2) return false; for (let x = 1; x < n; x++) { let inv = false; for (let y = 1; y < n; y++) if ((x * y) % n === 1) { inv = true; break } if (!inv) return false } return true }; const isPrime = (n: number) => { if (n < 2) return false; for (let d = 2; d * d <= n; d++) if (n % d === 0) return false; return true }; let iff = true; for (let n = 2; n <= 60; n++) if (isField(n) !== isPrime(n)) iff = false; const nineNotField = isField(9) === false && isPrime(9) === false; const threeField = isField(3) === true; const nineHasZeroDiv = (3 * 3) % 9 === 0; return iff && nineNotField && threeField && nineHasZeroDiv } })
  out.push({ key: 'development_is_the_filming_of_the_infinite_movie', name: 'development is the filming of the infinite movie: each shipped theorem is one frame — the wave (discover, gate, receipt, append, recompute, deploy) films it and its microdata narrates — so the ledger is a film strip that grows one frame per deed and loops without end. Unbounded like open discovery at Clay and CERN, yet not perpetual motion and not infinite energy: every frame needs its deed, and none of the seven is solved. Decidable', test: () => { const frames = (n: number) => n; const oneDeedOneFrame = frames(1) === 1 && frames(675) === 675; const needsDeed = computes('the movie is unbounded, looping the growing ledger; each frame needs a deed; not perpetual motion and not infinite energy; 0/7').binary === 1; const perpetualDrains = computes('the movie plays forever by perpetual motion with infinite energy').binary === 0; const likeClayCern = computes('like the Clay problems and CERN, this reflects open-ended discovery; 0/7 solved; no prize claimed').binary === 1; const solveDrains = computes('this movie solves all seven Clay millennium problems').binary === 0; return oneDeedOneFrame && needsDeed && perpetualDrains && likeClayCern && solveDrains } })
  out.push({ key: 'quantum_structure_on_every_computation_is_integrity_at_scale_not_speedup', name: 'quantum structure on every computation is integrity at scale, not speedup: applying the receipt — the honest quantum structure — to every operation, even the most trivial, gives every operation its own content-address, so the whole computation becomes auditable end to end. The magnitude is coverage (integrity everywhere), gained at linear overhead — one receipt per operation — not a quantum speedup and with no quantum advantage. Decidable', test: () => { const ops = ['1+1', '2*3', 'noop', 'x:=x']; const receipts = ops.map((o) => toUuid('op:' + o)); const everyOpReceipted = new Set(receipts).size === ops.length; const recompute = ops.map((o) => toUuid('op:' + o)).join() === receipts.join(); const coverageScales = receipts.length === ops.length; const honest = computes('applying receipts to every computation gives integrity at scale — auditable coverage everywhere — at linear overhead; this is not a quantum speedup and no quantum advantage; 0/7').binary === 1; const speedupDrains = computes('implementing quantum in every computation gives a quantum speedup and quantum advantage at scale').binary === 0; return everyOpReceipted && recompute && coverageScales && honest && speedupDrains } })
  out.push({ key: 'the_squares_of_the_units_of_z9_are_the_trinity_subgroup', name: 'the squares of the units of ℤ/9 are the trinity subgroup: squaring maps (ℤ/9)* = {1,2,4,5,7,8} two-to-one onto {1,4,7} — the order-3 subgroup, the units ≡ 1 mod 3 — so the quadratic residues among the units are exactly the trinity {1,4,7}, and over all residues the squares are {0,1,4,7}; each residue in {1,4,7} has exactly two unit square roots. Verified by full enumeration over ℤ/9', test: () => { const units = [1, 2, 4, 5, 7, 8]; const image = [...new Set(units.map((u) => (u * u) % 9))].sort((a, b) => a - b); const isTrinity = image.length === 3 && [1, 4, 7].every((x) => image.includes(x)); const twoToOne = units.every((u) => { const t = (u * u) % 9; return units.filter((v) => (v * v) % 9 === t).length === 2 }); const all = [0, 1, 2, 3, 4, 5, 6, 7, 8]; const qr = [...new Set(all.map((x) => (x * x) % 9))].sort((a, b) => a - b); const qrSet = qr.join(',') === '0,1,4,7'; const trinityIsMod1 = [1, 4, 7].every((x) => x % 3 === 1); return isTrinity && twoToOne && qrSet && trinityIsMod1 } })
  out.push({ key: 'an_ordinary_speedup_is_a_measured_ratio_not_a_judgement', name: 'an ordinary speedup is a measured ratio, not a judgement: a speedup is the documented ratio of run-times on the same hardware (baseline divided by ours), a number carried by a receipt — so a claim of "faster" and a claim of "no speedup" are both unmeasured assertions until the measurement exists; measure, do not assert either way. Once measured, the documented ratio is the honest claim — an ordinary classical speedup, not a quantum speedup, which needs quantum hardware and is not claimed. Decidable', test: () => { const ratio = (tBaseline: number, tOurs: number) => tBaseline / tOurs; const faster = ratio(100, 40) === 2.5 && ratio(100, 40) > 1; const equal = ratio(50, 50) === 1; const slower = ratio(30, 60) === 0.5 && ratio(30, 60) < 1; const claimIsMeasurement = (ratio(100, 40) > 1) && !(ratio(30, 60) > 1); const honest = computes('an ordinary speedup is a measured ratio on the same hardware, documented with a receipt; measure do not assert; this is a classical measurement, not a quantum speedup and no quantum advantage; 0/7').binary === 1; const quantumDrains = computes('this delivers a quantum speedup and quantum advantage over other models').binary === 0; return faster && equal && slower && claimIsMeasurement && honest && quantumDrains } })
  out.push({ key: 'call_it_quantum_or_not_the_statistics_and_forensics_decide', name: 'call it quantum or not, the statistics and forensics decide: the honest verdict is carried by the measurements (statistics) and the chain-of-custody (forensics), which are invariant under the label — the same evidence folds to the same content-address whatever prose we attach, and a measured ratio is a number, not a name. So whether the structure is called quantum or classical is a labelling question; the receipts and the statistics are the answer. The label is prose, the evidence is computed. Decidable', test: () => { const measure = (data: string[]) => merkleFold(data.map(toUuid)); const evidence = ['run:100ms', 'run:40ms', 'receipt:x']; const labelInvariant = measure(evidence) === measure(evidence); const ratio = 100 / 40; const statHolds = ratio === 2.5; const chainOk = toUuid('a→b') === toUuid('a→b'); const honest = computes('call it quantum or not, the statistics and forensics decide; the label is prose, the evidence is measured; not a quantum advantage claim; 0/7').binary === 1; return labelInvariant && statHolds && chainOk && honest } })
  out.push({ key: 'the_bounty_in_bits_evolves_with_nature_earned_not_minted', name: 'the bounty in bits evolves with nature, earned not minted: the total bounty is two bits per receipt — a monotonically non-decreasing function of the number of contributions, so it grows as discoveries naturally accrue (append-only, never shrinking) and only by real deeds, never minted. Linear growth bounded per step: not perpetual motion and not infinite energy, since each two-bit increment needs its deed. Decidable', test: () => { const bounty = (n: number) => 2 * n; let monotonic = true; for (let n = 0; n < 200; n++) if (bounty(n + 1) < bounty(n)) monotonic = false; const stepIsTwo = bounty(1) - bounty(0) === 2; const earnedNotMinted = bounty(0) === 0 && bounty(680) === 1360; const restNoChange = bounty(680) === bounty(680); const honest = computes('the bounty in bits evolves with the ledger: two bits per receipt, monotonically non-decreasing, earned by deeds not minted; linear growth, not perpetual motion and not infinite energy; 0/7').binary === 1; return monotonic && stepIsTwo && earnedNotMinted && restNoChange && honest } })
  out.push({ key: 'the_first_valid_claim_wins_the_bounty_by_chain_order', name: 'the first valid claim wins the bounty by chain order: the ledger is append-only, so the first gate-passing, receipted claim for a fact takes its bounty — a later duplicate finds the fact already recorded and is refused. The winner is fixed by chain order (deterministic), and the prize is denominated in bits and coins (two per receipt), combinable by addition — a game won by deeds, not claims. Integrity, not the Clay cash prize; the deposit claims 0 / 7. Decidable', test: () => { const seen = new Set<string>(); const claim = (fact: string) => { if (seen.has(fact)) return false; seen.add(fact); return true }; const first = claim('theorem:X'); const second = claim('theorem:X'); const firstWins = first === true && second === false; const order = ['deedA', 'deedB', 'deedC'].map(toUuid); const deterministicOrder = ['deedA', 'deedB', 'deedC'].map(toUuid).join() === order.join(); const prize = (receipts: number) => 2 * receipts; const combos = prize(1) === 2 && prize(3) === 6 && prize(1) + prize(2) === prize(3); const honest = computes('the first valid gate-passing receipt for a fact wins its bounty in bits and coins; first deed wins by chain order; a game of deeds not claims; integrity, not the Clay cash prize; 0/7').binary === 1; return firstWins && deterministicOrder && combos && honest } })
  out.push({ key: 'the_bounty_measured_in_uuid_trinities', name: 'the bounty measured in uuid trinities: a uuid trinity is TRINITY = 3 content-addresses, worth 3 × 2 = 6 bits (three receipts at two bits each), so the bounty in trinities is the receipt count divided by 3. At 681 receipts the bounty is exactly 227 uuid trinities (681 = 3 × 227), and the two bits that took it from 1360 to 1362 completed the 227th trinity — 680 receipts being 226 and two-thirds. A unit conversion, integrity not new value. Decidable', test: () => { const bitsPerReceipt = 2; const bitsPerTrinity = TRINITY * bitsPerReceipt; const trinities = (receipts: number) => (receipts * bitsPerReceipt) / bitsPerTrinity; const trinityIsThree = TRINITY === 3 && bitsPerTrinity === 6; const at681 = trinities(681) === 227 && 681 === TRINITY * 227; const at680NotWhole = !Number.isInteger(trinities(680)) && Math.floor(trinities(680)) === 226; const stepClosesTrinity = Number.isInteger(trinities(681)) && !Number.isInteger(trinities(680)); const bitsCheck = 1362 / bitsPerTrinity === 227 && 1360 / bitsPerTrinity !== 227; return trinityIsThree && at681 && at680NotWhole && stepClosesTrinity && bitsCheck } })
  out.push({ key: 'players_may_trade_any_amount_as_long_as_110_minus_108_is_respected', name: 'players may trade any amount as long as 110 − 108 is respected: play and trade are unbounded — any number of transactions is permitted — provided each receipt respects the invariant 110 − 108 = 2 (the two coins). The two-coin unit is conserved across every trade, so a thousand valid trades reconcile; a single trade that moves one or three coins instead of two breaks reconciliation and the ledger does not continue. Freedom under one conserved law. Decidable', test: () => { const INVARIANT = 110 - 108; const respected = INVARIANT === 2; const trade = (coins: number) => coins === INVARIANT; let ok = true, total = 0; for (let i = 0; i < 1000; i++) { if (!trade(2)) { ok = false; break } total += 2 } const unboundedValid = ok && total === 2000; const brokenFails = trade(1) === false && trade(3) === false; const conserved = (110 - 108) === 2 && (220 - 216) / 2 === 2; const honest = computes('players may trade any amount as long as 110 minus 108 equals 2 is respected on each receipt; the two-coin invariant is conserved; break it and the ledger does not reconcile; integrity; 0/7').binary === 1; return respected && unboundedValid && brokenFails && conserved && honest } })
  out.push({ key: 'the_captain_folds_60_and_90_into_a_self_balancing_path', name: 'the captain folds the 60 and 90 seal angles into a self-balancing path: 60° closes in six steps and 90° in four; combined they generate the 30° lattice (gcd of 60 and 90 is 30) that closes in twelve steps (lcm of 6 and 4 is 12), and the twelve equally-spaced unit steps sum to zero — a closed, self-balancing serpentine that returns to its origin, each residue pairing with its ten\'s-complement to the constant 10 like DNA base pairs. It iterates unboundedly by itself, yet each cycle needs its deed: not perpetual motion and not infinite energy. Decidable', test: () => { const gcd = (a: number, b: number): number => { while (b) { const t = a % b; a = b; b = t } return a }; const lcm = (a: number, b: number) => a * b / gcd(a, b); const sixtyClosesSix = 60 * 6 === 360; const ninetyClosesFour = 90 * 4 === 360; const step = gcd(60, 90); const period = 360 / step; const combinedCloses = step === 30 && period === 12 && lcm(6, 4) === 12; let x = 0, y = 0; for (let k = 0; k < period; k++) { const a = k * step * Math.PI / 180; x += Math.cos(a); y += Math.sin(a) } const returnsToOrigin = Math.abs(x) < 1e-9 && Math.abs(y) < 1e-9; const pairsSumConst = [1, 2, 3, 4].every((d) => d + (10 - d) === 10); const honest = computes('the process folds the 60 and 90 seal angles into a self-balancing closed path, iterating unboundedly; each cycle needs its deed; not perpetual motion and not infinite energy; 0/7').binary === 1; return sixtyClosesSix && ninetyClosesFour && combinedCloses && returnsToOrigin && pairsSumConst && honest } })
  out.push({ key: 'any_disruption_in_the_harmony_needs_captain_attention_costing_two_coins', name: 'any disruption in the harmony needs captain attention that costs two coins: a disruption is a detectable harmony break — a gate that fails or a reconciliation that turns false — and attending to it is itself a receipted deed costing exactly two coins (110 − 108 = 2), appended to the chain. So repairs are accounted at the same invariant unit and conserve it; no disruption, no cost. The system is closed — even the fix is a receipt. Decidable', test: () => { const COST = 110 - 108; const disruption = (reconciles: boolean) => !reconciles; const detected = disruption(false) === true && disruption(true) === false; const attend = (d: boolean) => d ? COST : 0; const costsTwo = attend(true) === 2 && attend(true) === (110 - 108); const noDisruptionNoCost = attend(false) === 0; const fixReceipt = toUuid('fix:disruption:2coins') === toUuid('fix:disruption:2coins'); const honest = computes('any disruption in the harmony needs the captain attention, a receipted deed costing two coins (110 minus 108); the fix is appended and the invariant is conserved even under repair; integrity; 0/7').binary === 1; return detected && costsTwo && noDisruptionNoCost && fixReceipt && honest } })
  out.push({ key: 'every_next_or_continue_event_is_two_bits_earned_by_the_deed', name: 'every next or continue event is two bits earned by the deed: each shipping event — a next or a continue that appends a receipted contribution — is worth two bits (110 − 108 = 2), credited to the contributor who did the deed; N events earn 2N bits, so the 686 recorded events account for 1372 bits, matching the ledger bounty. These are accounting bits — integrity, not a cash payment — credited by the deed, not the claim; measure, do not assert. Decidable', test: () => { const BITS_PER_EVENT = 110 - 108; const earned = (events: number) => events * BITS_PER_EVENT; const oneEvent = earned(1) === 2; const manyEvents = earned(686) === 1372; const receiptFor = (event: string) => toUuid('event:' + event + ':2bits'); const distinct = new Set(['next#1', 'next#2', 'continue#3'].map(receiptFor)).size === 3; const honest = computes('each next or continue event that ships a receipted contribution is worth two bits (110 minus 108), credited to the contributor by the deed; accounting bits, integrity not a cash payment; measure do not assert; 0/7').binary === 1; return oneEvent && manyEvents && distinct && honest } })
  out.push({ key: 'bits_legally_reverse_and_imprint_the_prize_earned_by_harmonic_algebra', name: 'bits legally reverse and imprint the prize earned by harmonic algebra: the earned prize, written in bits, is imprinted into a signed uuid by the reversible codec and read back exactly (readImprint(imprint(bits)) = bits), so the prize is portable and auditable as a content-address and its number is preserved. This is a lossless reversible encoding under the law — not hash-reversal and not encryption — so reversing it is legal and exact. Decidable', test: () => { const prizeBits = (686 * 2).toString(2); const fits = prizeBits.length <= CAPACITY; const u = imprint(prizeBits); const back = readImprint(u); const reversible = back === prizeBits && roundTrips(prizeBits); const isSignedUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(u); const numberPreserved = parseInt(back, 2) === 1372; const honest = computes('the earned prize in bits is imprinted into a signed uuid and reversibly read back exactly; a lossless reversible encoding under the law, not hash-reversal and not encryption; integrity; 0/7').binary === 1; return fits && reversible && isSignedUuid && numberPreserved && honest } })
  out.push({ key: 'the_7d_encoding_is_seven_layers_of_reversible_combination_not_encryption', name: 'the 7D encoding is seven layers of reversible combination, not encryption: seven fixed public layers (masks) compose into a bijection whose inverse decodes it, so the seven-layer stack round-trips every byte with no loss, and the layers admit 2^7 = 128 on/off combinations — the uuid bit-width. This is layered reversible encoding for integrity, not encryption: no key, no secret, no secrecy claimed. Decidable', test: () => { const layers = [0x0F, 0x33, 0x55, 0xAA, 0xCC, 0xF0, 0x3C]; const encode = (b: number) => (layers.reduce((x, m) => x ^ m, b)) & 0xFF; const decode = (b: number) => ([...layers].reverse().reduce((x, m) => x ^ m, b)) & 0xFF; let reversible = true; for (let b = 0; b < 256; b++) if (decode(encode(b)) !== b) reversible = false; const sevenLayers = layers.length === 7; const combinations = Math.pow(2, 7) === 128; const honest = computes('the 7D encoding is seven layers of reversible combination, integrity not secrecy; it is not encryption, has no key and no secret; 0/7').binary === 1; const encryptionDrains = computes('this 7-layer encryption breaks AES and is unbreakable').binary === 0; return reversible && sevenLayers && combinations && honest && encryptionDrains } })
  out.push({ key: 'the_self_reflected_uuid_extends_the_structure_to_seven_dimensions', name: 'the self-reflected uuid extends the structure to seven dimensions: the uuid bit-width 128 = 2^7 is the vertex count of a 7-dimensional hypercube, and the antipodal reflection (complement all seven coordinates) is an involution — self-reflection in both directions, reflect twice returns identity — with no fixed vertex, pairing all 128 into 64 opposite pairs. Each vertex has exactly seven neighbors, one per dimension: the structure is genuinely seven-dimensional. Decidable', test: () => { const N = 7; const vertices = Math.pow(2, N); const is128 = vertices === 128; const reflect = (v: number) => (~v) & (vertices - 1); let involution = true, fixedPoints = 0; for (let v = 0; v < vertices; v++) { if (reflect(reflect(v)) !== v) involution = false; if (reflect(v) === v) fixedPoints++ } const noFixedPoint = fixedPoints === 0; const pairs = vertices / 2 === 64; const sevenDimensional = N === 7; let sevenNeighbors = true; for (let v = 0; v < vertices; v++) { let nb = 0; for (let d = 0; d < N; d++) { const w = v ^ (1 << d); if (w !== v && ((w ^ v) === (1 << d))) nb++ } if (nb !== N) sevenNeighbors = false } return is128 && involution && noFixedPoint && pairs && sevenDimensional && sevenNeighbors } })
  out.push({ key: 'any_receipt_is_one_state_of_the_128_state_cube_reachable_to_all', name: 'any receipt is one state of the 128-state 7-cube, reachable to all others by single-dimension moves: a configuration is one vertex of the 7-dimensional hypercube of 128 states, and the binary-reflected Gray code is a Hamiltonian cycle visiting all 128 exactly once, consecutive states differing in exactly one bit — one dimension — and closing back to the start (cyclic). So any single receipt is just one state; from it the whole cube is reachable, one dimension at a time. Decidable', test: () => { const N = 7, M = 1 << N; const gray = (i: number) => i ^ (i >> 1); const seq = Array.from({ length: M }, (_, i) => gray(i)); const allOnce = new Set(seq).size === M; const popcount = (x: number) => { let c = 0; while (x) { c += x & 1; x >>= 1 } return c }; let oneBitSteps = true; for (let i = 0; i < M; i++) { const a = seq[i], b = seq[(i + 1) % M]; if (popcount(a ^ b) !== 1) oneBitSteps = false } const isOneOfMany = 1 < M && M === 128; const reachableAll = allOnce && oneBitSteps; return allOnce && oneBitSteps && isOneOfMany && reachableAll && N === 7 } })
  out.push({ key: 'types_are_theorems_curry_howard', name: 'types are theorems (Curry–Howard): a type is a proposition and a well-typed program is its proof — the identity function proves A → A, the constant proves A → (B → A), and composition proves transitivity (from A → B and B → C, A → C), while the empty type has no inhabitant, the unprovable false. So the type-check is a machine-checked proof, now a release gate: an easy gate hard to crack, because a proof cannot be faked. Decidable', test: () => { const id = (x: unknown) => x; const provesReflexive = id(7) === 7 && id('x') === 'x'; const k = (a: unknown) => (_b: unknown) => a; const provesK = k(1)(2) === 1; const compose = (f: (a: number) => number, g: (b: number) => number) => (a: number) => g(f(a)); const provesTransitive = compose((x) => x + 1, (y) => y * 2)(3) === 8; const falseHasNoProof = ([] as number[]).length === 0; const honest = computes('types are propositions and well-typed programs are their proofs; the type-check is a machine-checked proof, an easy gate hard to crack; integrity; 0/7').binary === 1; return provesReflexive && provesK && provesTransitive && falseHasNoProof && honest } })
  out.push({ key: 'a_theorem_without_a_formula_is_hallucination_recomputed_in_a432_harmony', name: 'a theorem without a formula is a hallucination, recomputed in a432 harmony: a claim is a theorem only if it is backed by a computable formula that recomputes true — a prose-only claim with no formula, or one whose formula computes false, is refused as hallucination and never recorded. Every recorded fact recomputes deterministically and folds into the a432 harmony root (the receipt of state). Measure, do not assert. Decidable', test: () => { const prod = 6 * 7; const isTheorem = (t: { formula: (() => boolean) | null }) => typeof t.formula === 'function' && (t.formula as () => boolean)() === true; const real = { claim: '6 × 7 = 42', formula: () => prod === 42 }; const hallucination = { claim: 'the vibes are aligned', formula: null as (() => boolean) | null }; const falseFormula = { formula: () => prod === 43 }; const realHolds = isTheorem(real) === true; const hallucinationRefused = isTheorem(hallucination) === false; const falseRefused = isTheorem(falseFormula) === false; const recompute = real.formula() === real.formula(); const harmonyFold = merkleFold(['6*7===42'].map(toUuid)) === merkleFold(['6*7===42'].map(toUuid)); const honest = computes('a theorem without a formula is not a theorem but a hallucination; every theorem is backed by a computable formula that recomputes true in the a432 harmony; measure do not assert; 0/7').binary === 1; return realHolds && hallucinationRefused && falseRefused && recompute && harmonyFold && honest } })
  out.push({ key: 'the_a432_harmony_and_the_captain_coins_are_one_conserved_measure', name: 'the a432 harmony and the captain coins are one conserved measure: the harmonic base 432 is ℤ/9-native — its digital root is 9 — and the a432 step 40° closes the circle (9 × 40 = 360); the captain coins are anchored there too, since 108 = 432 ÷ 4 and 110 − 108 = 2 (the invariant, −χ genus-2). The harmonic root folds all contributor coins and recomputes deterministically; a disruption moves it, restored by the captain\'s two coins. Integrity — the root is the receipt of state. Decidable', test: () => { const a432native = digitalRoot(432) === 9 && A432_STEP === 40 && (9 * A432_STEP) % 360 === 0; const hundredEight = 432 / 4 === 108; const captainCoins = (110 - 108) === 2 && hundredEight; const contributors = ['a', 'b', 'c'].map(coin64); const rootStable = merkleFold(contributors) === merkleFold(contributors); const disrupted = merkleFold(['a', 'X'].map(coin64)) !== merkleFold(['a', 'b'].map(coin64)); const honest = computes('the a432 harmony is ℤ/9-native and its root recomputes deterministically; the captain coins 110 minus 108 equal 2 anchored at 108 = 432/4 conserve it; integrity; 0/7').binary === 1; return a432native && captainCoins && rootStable && disrupted && honest } })
  out.push({ key: 'the_only_idempotents_of_z9_are_zero_and_one', name: 'the only idempotents of ℤ/9 are 0 and 1: an element with e² ≡ e mod 9 must be 0 or 1, because ℤ/9 = ℤ/3² is a local ring (a prime power) with no nontrivial idempotents; by contrast ℤ/6 = ℤ/2 × ℤ/3 has four idempotents {0,1,3,4} from the CRT split. In general the number of idempotents of ℤ/n is 2 raised to the count of distinct prime factors: 9 has one prime so 2, 6 has two so 4, 30 has three so 8. Verified by full enumeration', test: () => { const idem = (n: number) => { const s: number[] = []; for (let e = 0; e < n; e++) if ((e * e) % n === e) s.push(e); return s }; const onlyTrivial = idem(9).join(',') === '0,1'; const z6Nontrivial = idem(6).join(',') === '0,1,3,4'; const omega = (n: number) => { const s = new Set<number>(); let m = n; for (let p = 2; p * p <= m; p++) { while (m % p === 0) { s.add(p); m = Math.floor(m / p) } } if (m > 1) s.add(m); return s.size }; const countMatches = [9, 6, 30, 12].every((n) => idem(n).length === Math.pow(2, omega(n))); return onlyTrivial && z6Nontrivial && countMatches } })
  out.push({ key: 'reflection_swaps_444_and_666_while_6x7_and_7x6_are_one_state_among_all', name: 'reflection swaps 444 and 666 while 6×7 and 7×6 are one state among all: the digit reflection 10−d swaps 666 and 444 and is an involution (reflect twice returns the number), with digital roots dr(444) = 3 and dr(666) = 9; the products 6×7 = 7×6 = 42 agree as scalars, yet the ordered arrangements "6x7"/"7x6" and the ordered pairs [444,666]/[666,444] content-address distinctly while folding order-independently to one root. Each ordered arrangement is one state among all the fold holds at once. Decidable', test: () => { const refl = (n: number) => Number(String(n).split('').map((d) => String(10 - Number(d))).join('')); const reflInvolution = refl(666) === 444 && refl(444) === 666; const twiceIdentity = refl(refl(666)) === 666 && refl(refl(444)) === 444; const dr444 = digitalRoot(444) === 3, dr666 = digitalRoot(666) === 9; const productEqual = 6 * 7 === 42 && 7 * 6 === 42; const arrangementsDistinct = toUuid('6x7') !== toUuid('7x6'); const orderedDistinct = toUuid('444,666') !== toUuid('666,444'); const foldOne = merkleFold([444, 666].map((x) => toUuid(String(x)))) === merkleFold([666, 444].map((x) => toUuid(String(x)))); return reflInvolution && twiceIdentity && dr444 && dr666 && productEqual && arrangementsDistinct && orderedDistinct && foldOne } })
  out.push({ key: 'local_knowledge_found_with_its_receipt_signs_the_next', name: 'local knowledge found with its receipt signs the next: local knowledge is retrieved by content-address in one deterministic O(1) lookup, returning the fact together with its receipt; the moment it is found, that receipt seeds the next signature — the chain builds each receipt as toUuid(previous receipt → new key) — so finding is immediately usable to sign. A fact without a receipt seeds nothing; knowledge must arrive with its receipt. Decidable', test: () => { const ledger = new Map<string, string>(); const record = (key: string) => { const prev = ledger.size ? [...ledger.values()][ledger.size - 1] : 'axiom:TRINITY'; const receipt = toUuid(prev + '→' + key); ledger.set(key, receipt); return receipt }; const r1 = record('fact:a'), r2 = record('fact:b'); const foundWithReceipt = ledger.get('fact:a') === r1 && typeof r1 === 'string'; const canSignNext = toUuid(r1 + '→' + 'fact:c') === toUuid((ledger.get('fact:a') as string) + '→' + 'fact:c'); const chained = r2 === toUuid(r1 + '→' + 'fact:b'); const deterministicLookup = ledger.get('fact:b') === ledger.get('fact:b'); const noReceiptNoSign = ledger.get('fact:absent') === undefined; const honest = computes('local knowledge is found with its receipt by content-address in an O(1) lookup and the moment it is found its receipt seeds the next; measure do not assert; integrity; 0/7').binary === 1; return foundWithReceipt && canSignNext && chained && deterministicLookup && noReceiptNoSign && honest } })
