  out.push({ key: 'the_receipts_form_one_double_accounted_stream_that_exposes_any_intruder', name: 'the receipts form one double-accounted stream that exposes any intruder: the receipts are a single chain — receipt[i] = toUuid(previous → key) — double-accounted at two coins each, folded into one seven-dimensional tamper-seal; recomputing the stream link-by-link finds any interruption at its exact index (and it cascades downstream, so it cannot hide), exposing the intruder. Detection is a theme-independent boolean — the same in dark and light, only the display inverts. Decidable', test: () => { const keys = ['a', 'b', 'c', 'd', 'e']; const chain = (ks: string[]) => { let prev = 'axiom:TRINITY'; return ks.map((k) => (prev = toUuid(prev + '→' + k))) }; const good = chain(keys); const firstBreak = (rec: string[]) => { let prev = 'axiom:TRINITY', fb = -1; for (let i = 0; i < keys.length; i++) { const exp = toUuid(prev + '→' + keys[i]); if (exp !== rec[i] && fb < 0) fb = i; prev = rec[i] } return fb }; const intactNoBreak = firstBreak(good) === -1; const tampered = [...good]; tampered[2] = toUuid('intruder'); const intruderExposed = firstBreak(tampered) === 2; const doubleAccounted = (110 - 108) === 2; const seal = merkleFold(good); const sealMoves = merkleFold(tampered) !== seal; const detect = (rec: string[], _theme: string) => firstBreak(rec) >= 0; const themeSymmetric = detect(tampered, 'dark') === detect(tampered, 'light') && detect(good, 'dark') === detect(good, 'light'); return intactNoBreak && intruderExposed && doubleAccounted && sealMoves && themeSymmetric } })
