  out.push({ key: 'local_allocation_maximizes_value_per_two_coins', name: 'local allocation maximizes value per two coins: modeling resources (cpu, gpu, memory, storage, network, sensors, drivers) by value-per-coin, the optimal spend of the two coins is greedy — the two highest-value resources — which for unit-cost coins is optimal and beats an equal split across all seven. The allocation is deterministic and reproducible, computed locally to get the most from each two-coin unit of developer funding. A decidable model, not a live hardware scheduler. Decidable', test: () => { const res = [{ name: 'cpu', v: 5 }, { name: 'gpu', v: 8 }, { name: 'memory', v: 4 }, { name: 'storage', v: 2 }, { name: 'network', v: 3 }, { name: 'sensors', v: 6 }, { name: 'drivers', v: 1 }]; const budget = 110 - 108; const byValue = [...res].sort((a, b) => b.v - a.v); const greedy = byValue.slice(0, budget).reduce((s, r) => s + r.v, 0); const total = res.reduce((s, r) => s + r.v, 0); const equalSplit = total * (budget / res.length); const greedyBeatsEqual = greedy >= equalSplit; const optimalIsTop2 = greedy === 8 + 6; const deterministic = byValue.map((r) => r.name).join(',') === [...res].sort((a, b) => b.v - a.v).map((r) => r.name).join(','); const honest = computes('local allocation distributes the two coins to the highest-value resources first, maximizing value per two coins; a decidable computed model, not a live hardware scheduler; measure do not assert; integrity; 0/7').binary === 1; return greedyBeatsEqual && optimalIsTop2 && deterministic && honest } })
